-- Stage 6: trusted social coordination. Apply after 0010_stage34_profile_access.sql.
alter table public.profiles add column if not exists activity_visibility text not null default 'friends';
alter table public.profiles add column if not exists allow_friend_requests boolean not null default true;
alter table public.profiles add column if not exists allow_event_messages boolean not null default true;
alter table public.conversations add column if not exists plan_id uuid references public.plans(id) on delete set null;
alter table public.conversations add column if not exists title text;
alter table public.conversations add column if not exists updated_at timestamptz not null default now();
alter table public.conversations drop constraint if exists conversations_kind_check;
alter table public.conversations add constraint conversations_kind_check check(kind in('direct','event_room','plan_room','organizer','support'));
alter table public.conversation_members add column if not exists muted_until timestamptz;
alter table public.conversation_members add column if not exists last_read_message_id bigint;
alter table public.conversation_members add column if not exists left_at timestamptz;
alter table public.messages add column if not exists reply_to_id bigint references public.messages(id) on delete set null;
alter table public.messages add column if not exists message_type text not null default 'text';
alter table public.messages add column if not exists metadata jsonb not null default '{}'::jsonb;
alter table public.messages add column if not exists edited_at timestamptz;
alter table public.messages add column if not exists deleted_at timestamptz;
create table if not exists public.friend_close_friends(profile_id uuid references public.profiles(id) on delete cascade,friend_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(profile_id,friend_id),check(profile_id<>friend_id));
create table if not exists public.host_follows(profile_id uuid references public.profiles(id) on delete cascade,host_profile_id uuid references public.host_profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(profile_id,host_profile_id));
create table if not exists public.content_shares(id bigint generated always as identity primary key,sender_id uuid not null references public.profiles(id) on delete cascade,recipient_id uuid references public.profiles(id) on delete cascade,plan_id uuid references public.plans(id) on delete cascade,event_id uuid references public.events(id) on delete cascade,location_id uuid references public.locations(id) on delete cascade,note text,created_at timestamptz not null default now(),check(num_nonnulls(recipient_id,plan_id)=1),check(num_nonnulls(event_id,location_id)=1));
create table if not exists public.message_reactions(message_id bigint references public.messages(id) on delete cascade,profile_id uuid references public.profiles(id) on delete cascade,emoji text not null,created_at timestamptz not null default now(),primary key(message_id,profile_id,emoji));
create table if not exists public.social_comments(id bigint generated always as identity primary key,author_id uuid not null references public.profiles(id) on delete cascade,event_id uuid references public.events(id) on delete cascade,location_id uuid references public.locations(id) on delete cascade,parent_id bigint references public.social_comments(id) on delete cascade,body text not null,pinned_at timestamptz,edited_at timestamptz,deleted_at timestamptz,created_at timestamptz not null default now(),check(num_nonnulls(event_id,location_id)=1));
create table if not exists public.social_reports(id bigint generated always as identity primary key,reporter_id uuid not null references public.profiles(id) on delete cascade,target_type text not null,target_id text not null,category text not null,details text,evidence jsonb not null default '{}'::jsonb,status text not null default 'open',created_at timestamptz not null default now());
create table if not exists public.notification_preferences(profile_id uuid primary key references public.profiles(id) on delete cascade,in_app_enabled boolean not null default true,email_enabled boolean not null default true,friend_requests boolean not null default true,shares boolean not null default true,messages boolean not null default true,comments boolean not null default true,event_reminders boolean not null default true,event_changes boolean not null default true,host_announcements boolean not null default true,marketing boolean not null default false,quiet_start time,quiet_end time,timezone text not null default 'America/Toronto',updated_at timestamptz not null default now());
create table if not exists public.notifications(id bigint generated always as identity primary key,profile_id uuid not null references public.profiles(id) on delete cascade,actor_id uuid references public.profiles(id) on delete set null,kind text not null,title text not null,body text not null,href text,metadata jsonb not null default '{}'::jsonb,read_at timestamptz,created_at timestamptz not null default now());
create index if not exists notifications_profile_idx on public.notifications(profile_id,read_at,created_at desc);
create table if not exists public.notification_outbox(id bigint generated always as identity primary key,notification_id bigint references public.notifications(id) on delete cascade,profile_id uuid not null references public.profiles(id) on delete cascade,email text,category text not null,subject text not null,body text not null,status text not null default 'pending',attempts integer not null default 0,next_attempt_at timestamptz not null default now(),provider_message_id text,last_error text,created_at timestamptz not null default now(),sent_at timestamptz);
create table if not exists public.host_announcements(id bigint generated always as identity primary key,host_profile_id uuid not null references public.host_profiles(id) on delete cascade,event_id uuid references public.events(id) on delete set null,author_id uuid not null references public.profiles(id),title text not null,body text not null,created_at timestamptz not null default now());
create or replace function public.profiles_are_friends(a uuid,b uuid) returns boolean language sql stable security definer set search_path=public as $$select a<>b and exists(select 1 from public.friendships f where f.state='accepted' and((f.requester_id=a and f.addressee_id=b)or(f.requester_id=b and f.addressee_id=a)))and not exists(select 1 from public.blocks x where(x.blocker_id=a and x.blocked_id=b)or(x.blocker_id=b and x.blocked_id=a))$$;
create or replace function public.is_conversation_member(target uuid,member uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.conversation_members where conversation_id=target and profile_id=member and left_at is null)$$;
create or replace function public.queue_notification_v1(target_profile uuid,actor uuid,notification_kind text,notification_title text,notification_body text,notification_href text default null,notification_metadata jsonb default '{}'::jsonb) returns bigint language plpgsql security definer set search_path=public as $$declare created bigint;p public.notification_preferences%rowtype;e text;begin insert into public.notification_preferences(profile_id)values(target_profile)on conflict do nothing;select * into p from public.notification_preferences where profile_id=target_profile;if p.in_app_enabled then insert into public.notifications(profile_id,actor_id,kind,title,body,href,metadata)values(target_profile,actor,left(notification_kind,80),left(notification_title,180),left(notification_body,1000),notification_href,coalesce(notification_metadata,'{}'))returning id into created;end if;if p.email_enabled then select email into e from auth.users where id=target_profile;if e is not null then insert into public.notification_outbox(notification_id,profile_id,email,category,subject,body)values(created,target_profile,e,left(notification_kind,80),left(notification_title,180),left(notification_body,4000));end if;end if;return created;end$$;
create or replace function public.search_social_profiles_v1(search_term text) returns table(id uuid,display_name text,username text,city text,bio text,mutual_count bigint,is_friend boolean,request_state text) language sql stable security definer set search_path=public as $$with c as(select p.id,p.display_name,p.username,p.city,p.bio from public.profiles p where p.id<>auth.uid()and p.suspended_at is null and(p.allow_friend_requests or public.profiles_are_friends(auth.uid(),p.id))and not exists(select 1 from public.blocks b where(b.blocker_id=auth.uid()and b.blocked_id=p.id)or(b.blocker_id=p.id and b.blocked_id=auth.uid()))and(p.username ilike '%'||trim(leading '@' from search_term)||'%'or p.display_name ilike '%'||trim(search_term)||'%')limit 30)select c.*,(select count(*)from public.profiles m where public.profiles_are_friends(auth.uid(),m.id)and public.profiles_are_friends(c.id,m.id)),public.profiles_are_friends(auth.uid(),c.id),(select f.state from public.friendships f where(f.requester_id=auth.uid()and f.addressee_id=c.id)or(f.requester_id=c.id and f.addressee_id=auth.uid())limit 1)from c$$;
create or replace function public.friend_profile_by_username_v1(target_username text) returns uuid language sql stable security definer set search_path=public as $$select id from public.profiles where lower(username)=lower(trim(leading '@' from target_username))and public.profiles_are_friends(auth.uid(),id)limit 1$$;
create or replace function public.send_friend_request_v1(target uuid) returns text language plpgsql security definer set search_path=public as $$declare actor uuid:=auth.uid();begin if actor is null or actor=target or exists(select 1 from public.blocks where(blocker_id=actor and blocked_id=target)or(blocker_id=target and blocked_id=actor))then raise exception 'profile unavailable';end if;if not coalesce((select allow_friend_requests from public.profiles where id=target),false)then raise exception 'friend requests disabled';end if;if exists(select 1 from public.friendships where requester_id=target and addressee_id=actor and state='pending')then update public.friendships set state='accepted' where requester_id=target and addressee_id=actor;perform public.queue_notification_v1(target,actor,'friend_accepted','Friend request accepted','You are now friends.','/friends');return 'accepted';end if;insert into public.friendships(requester_id,addressee_id,state,created_at)values(actor,target,'pending',now())on conflict(requester_id,addressee_id)do update set state='pending',created_at=now();perform public.queue_notification_v1(target,actor,'friend_request','New friend request','Someone wants to make plans with you.','/friends');return 'pending';end$$;
create or replace function public.respond_friend_request_v1(target uuid,response text) returns text language plpgsql security definer set search_path=public as $$declare s text:=case when response='accept'then'accepted'else'declined'end;begin update public.friendships set state=s where requester_id=target and addressee_id=auth.uid()and state='pending';if not found then raise exception 'request unavailable';end if;if s='accepted'then perform public.queue_notification_v1(target,auth.uid(),'friend_accepted','Friend request accepted','You are now friends.','/friends');end if;return s;end$$;
create or replace function public.remove_friend_v1(target uuid) returns boolean language plpgsql security definer set search_path=public as $$begin update public.friendships set state='removed'where(requester_id=auth.uid()and addressee_id=target)or(requester_id=target and addressee_id=auth.uid());delete from public.friend_close_friends where(profile_id=auth.uid()and friend_id=target)or(profile_id=target and friend_id=auth.uid());return true;end$$;
create or replace function public.set_close_friend_v1(target uuid,enabled boolean) returns boolean language plpgsql security definer set search_path=public as $$begin if not public.profiles_are_friends(auth.uid(),target)then raise exception 'friend unavailable';end if;if enabled then insert into public.friend_close_friends values(auth.uid(),target,now())on conflict do nothing;else delete from public.friend_close_friends where profile_id=auth.uid()and friend_id=target;end if;return enabled;end$$;
create or replace function public.block_profile_v1(target uuid) returns boolean language plpgsql security definer set search_path=public as $$begin if target=auth.uid()then raise exception 'invalid block';end if;insert into public.blocks(blocker_id,blocked_id)values(auth.uid(),target)on conflict do nothing;perform public.remove_friend_v1(target);return true;end$$;
create or replace function public.unblock_profile_v1(target uuid) returns boolean language plpgsql security definer set search_path=public as $$begin delete from public.blocks where blocker_id=auth.uid()and blocked_id=target;return found;end$$;
create or replace function public.follow_host_v1(target uuid,enabled boolean) returns boolean language plpgsql security definer set search_path=public as $$begin if enabled then insert into public.host_follows values(auth.uid(),target,now())on conflict do nothing;else delete from public.host_follows where profile_id=auth.uid()and host_profile_id=target;end if;return enabled;end$$;
create or replace function public.open_direct_conversation_v1(target uuid) returns uuid language plpgsql security definer set search_path=public as $$declare actor uuid:=auth.uid();cid uuid;begin if not public.profiles_are_friends(actor,target)then raise exception 'friend unavailable';end if;select c.id into cid from public.conversations c where c.kind='direct'and public.is_conversation_member(c.id,actor)and public.is_conversation_member(c.id,target)limit 1;if cid is null then insert into public.conversations(kind,created_by)values('direct',actor)returning id into cid;insert into public.conversation_members(conversation_id,profile_id,member_role)values(cid,actor,'owner'),(cid,target,'member');end if;return cid;end$$;
create or replace function public.open_support_conversation_v1() returns uuid language plpgsql security definer set search_path=public as $$declare cid uuid;begin select c.id into cid from public.conversations c join public.conversation_members m on m.conversation_id=c.id where c.kind='support'and m.profile_id=auth.uid()and m.left_at is null limit 1;if cid is null then insert into public.conversations(kind,created_by,title)values('support',auth.uid(),'Puddle support')returning id into cid;insert into public.conversation_members values(cid,auth.uid(),'owner',now(),null,null,null);end if;return cid;end$$;
create or replace function public.send_message_v1(target uuid,message_body text,reply_target bigint default null,message_kind text default 'text',message_metadata jsonb default '{}'::jsonb) returns bigint language plpgsql security definer set search_path=public as $$declare mid bigint;begin if not public.is_conversation_member(target)then raise exception 'not authorized';end if;insert into public.messages(conversation_id,sender_id,body,reply_to_id,message_type,metadata)values(target,auth.uid(),left(coalesce(nullif(trim(message_body),''),'Attachment'),5000),reply_target,case when message_kind in('text','attachment','system')then message_kind else'text'end,coalesce(message_metadata,'{}'))returning id into mid;update public.conversations set updated_at=now()where id=target;insert into public.notifications(profile_id,actor_id,kind,title,body,href)select profile_id,auth.uid(),'message','New message',left(coalesce(message_body,'Attachment'),180),'/inbox/'||target from public.conversation_members where conversation_id=target and profile_id<>auth.uid()and left_at is null and(muted_until is null or muted_until<now());return mid;end$$;
create or replace function public.edit_message_v1(target bigint,new_body text) returns boolean language plpgsql security definer set search_path=public as $$begin update public.messages set body=left(trim(new_body),5000),edited_at=now()where id=target and sender_id=auth.uid()and deleted_at is null;return found;end$$;
create or replace function public.delete_message_v1(target bigint) returns boolean language plpgsql security definer set search_path=public as $$begin update public.messages set body='Message deleted',state='author_deleted',deleted_at=now(),metadata='{}'where id=target and sender_id=auth.uid();return found;end$$;
create or replace function public.react_message_v1(target bigint,reaction text) returns boolean language plpgsql security definer set search_path=public as $$begin if not exists(select 1 from public.messages m where m.id=target and public.is_conversation_member(m.conversation_id))then raise exception 'not authorized';end if;if exists(select 1 from public.message_reactions where message_id=target and profile_id=auth.uid()and emoji=left(reaction,16))then delete from public.message_reactions where message_id=target and profile_id=auth.uid()and emoji=left(reaction,16);return false;end if;insert into public.message_reactions values(target,auth.uid(),left(reaction,16),now());return true;end$$;
create or replace function public.mark_conversation_read_v1(target uuid,last_message bigint default null) returns boolean language plpgsql security definer set search_path=public as $$begin update public.conversation_members set last_read_message_id=coalesce(last_message,(select max(id)from public.messages where conversation_id=target))where conversation_id=target and profile_id=auth.uid();return found;end$$;
create or replace function public.mute_conversation_v1(target uuid,until_time timestamptz default null) returns boolean language plpgsql security definer set search_path=public as $$begin update public.conversation_members set muted_until=until_time where conversation_id=target and profile_id=auth.uid();return found;end$$;
create or replace function public.share_content_v1(target_kind text,target_id uuid,recipient_profile uuid default null,target_plan uuid default null,share_note text default null) returns bigint language plpgsql security definer set search_path=public as $$declare sid bigint;begin if num_nonnulls(recipient_profile,target_plan)<>1 then raise exception 'destination required';end if;if recipient_profile is not null and not public.profiles_are_friends(auth.uid(),recipient_profile)then raise exception 'friend unavailable';end if;if target_plan is not null and not public.can_edit_plan(target_plan)then raise exception 'plan unavailable';end if;insert into public.content_shares(sender_id,recipient_id,plan_id,event_id,location_id,note)values(auth.uid(),recipient_profile,target_plan,case when target_kind='event'then target_id end,case when target_kind='place'then target_id end,left(share_note,1000))returning id into sid;if recipient_profile is not null then perform public.queue_notification_v1(recipient_profile,auth.uid(),'share','Shared with you','A friend shared something with you.','/plans');end if;return sid;end$$;
create or replace function public.create_social_comment_v1(target_kind text,target_id uuid,comment_body text,parent_comment bigint default null) returns bigint language plpgsql security definer set search_path=public as $$declare cid bigint;begin if nullif(trim(comment_body),'')is null then raise exception 'comment required';end if;if parent_comment is not null and not exists(select 1 from public.social_comments where id=parent_comment and parent_id is null)then raise exception 'reply unavailable';end if;insert into public.social_comments(author_id,event_id,location_id,parent_id,body)values(auth.uid(),case when target_kind='event'then target_id end,case when target_kind='place'then target_id end,parent_comment,left(trim(comment_body),2000))returning id into cid;return cid;end$$;
create or replace function public.report_social_target_v1(target_kind text,target_value text,report_category text,report_details text default null) returns bigint language plpgsql security definer set search_path=public as $$declare rid bigint;begin insert into public.social_reports(reporter_id,target_type,target_id,category,details)values(auth.uid(),left(target_kind,40),left(target_value,120),left(report_category,80),left(report_details,3000))returning id into rid;return rid;end$$;
create or replace function public.send_host_announcement_v1(target_host uuid,target_event uuid,announcement_title text,announcement_body text) returns bigint language plpgsql security definer set search_path=public as $$declare aid bigint;begin if not public.has_host_role(target_host,array['owner','editor','moderator'])and not public.is_admin()then raise exception 'not authorized';end if;insert into public.host_announcements(host_profile_id,event_id,author_id,title,body)values(target_host,target_event,auth.uid(),left(announcement_title,160),left(announcement_body,1000))returning id into aid;insert into public.notifications(profile_id,actor_id,kind,title,body,href)select profile_id,auth.uid(),'host_announcement',left(announcement_title,180),left(announcement_body,1000),'/notifications'from public.host_follows where host_profile_id=target_host;return aid;end$$;
alter table public.friend_close_friends enable row level security;alter table public.host_follows enable row level security;alter table public.content_shares enable row level security;alter table public.message_reactions enable row level security;alter table public.social_comments enable row level security;alter table public.social_reports enable row level security;alter table public.notification_preferences enable row level security;alter table public.notifications enable row level security;alter table public.notification_outbox enable row level security;alter table public.host_announcements enable row level security;
drop policy if exists "friendship participants" on public.friendships;drop policy if exists "own blocks" on public.blocks;drop policy if exists "conversation participants" on public.conversations;drop policy if exists "messages visible to members" on public.messages;drop policy if exists "members send messages" on public.messages;
create policy "friendship participants read" on public.friendships for select using(requester_id=auth.uid()or addressee_id=auth.uid()or public.is_admin());create policy "users read own blocks" on public.blocks for select using(blocker_id=auth.uid()or public.is_admin());create policy "users manage own close friends" on public.friend_close_friends for all using(profile_id=auth.uid())with check(profile_id=auth.uid()and public.profiles_are_friends(profile_id,friend_id));create policy "users manage own host follows" on public.host_follows for all using(profile_id=auth.uid())with check(profile_id=auth.uid());create policy "shares visible to participants" on public.content_shares for select using(sender_id=auth.uid()or recipient_id=auth.uid()or(plan_id is not null and public.is_plan_member(plan_id))or public.is_admin());create policy "conversation members read conversations" on public.conversations for select using(public.is_conversation_member(id)or public.is_admin());create policy "conversation members read memberships" on public.conversation_members for select using(profile_id=auth.uid()or public.is_conversation_member(conversation_id)or public.is_admin());create policy "members read visible messages" on public.messages for select using(public.is_conversation_member(conversation_id)or public.is_admin());create policy "members read message reactions" on public.message_reactions for select using(exists(select 1 from public.messages m where m.id=message_id and public.is_conversation_member(m.conversation_id))or public.is_admin());create policy "public reads active comments" on public.social_comments for select using(deleted_at is null or author_id=auth.uid()or public.is_admin());create policy "reporters read own reports" on public.social_reports for select using(reporter_id=auth.uid()or public.is_admin());create policy "users manage notification preferences" on public.notification_preferences for all using(profile_id=auth.uid())with check(profile_id=auth.uid());create policy "users read own notifications" on public.notifications for select using(profile_id=auth.uid()or public.is_admin());create policy "users update own notifications" on public.notifications for update using(profile_id=auth.uid())with check(profile_id=auth.uid());create policy "admins inspect notification outbox" on public.notification_outbox for select using(public.is_admin());create policy "host members read announcements" on public.host_announcements for select using(public.has_host_role(host_profile_id,array['owner','editor','moderator'])or public.is_admin());
revoke insert,update,delete on public.friendships,public.blocks,public.conversations,public.conversation_members,public.messages,public.message_reactions,public.content_shares,public.social_comments,public.social_reports,public.notification_outbox from authenticated;
do $$begin begin alter publication supabase_realtime add table public.messages;exception when duplicate_object then null;end;begin alter publication supabase_realtime add table public.message_reactions;exception when duplicate_object then null;end;begin alter publication supabase_realtime add table public.notifications;exception when duplicate_object then null;end;end$$;
grant execute on function public.search_social_profiles_v1(text),public.friend_profile_by_username_v1(text),public.send_friend_request_v1(uuid),public.respond_friend_request_v1(uuid,text),public.remove_friend_v1(uuid),public.set_close_friend_v1(uuid,boolean),public.block_profile_v1(uuid),public.unblock_profile_v1(uuid),public.follow_host_v1(uuid,boolean),public.open_direct_conversation_v1(uuid),public.open_support_conversation_v1(),public.send_message_v1(uuid,text,bigint,text,jsonb),public.edit_message_v1(bigint,text),public.delete_message_v1(bigint),public.react_message_v1(bigint,text),public.mark_conversation_read_v1(uuid,bigint),public.mute_conversation_v1(uuid,timestamptz),public.share_content_v1(text,uuid,uuid,uuid,text),public.create_social_comment_v1(text,uuid,text,bigint),public.report_social_target_v1(text,text,text,text),public.send_host_announcement_v1(uuid,uuid,text,text) to authenticated;
